window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6b3b266bcaea8fc7"]={"versions": [{"id": "FIG-6b3b266bcaea8fc7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Modellen für Timing-Ketten (Timing Chains) und deren zeitlichen Randbedingungen im Kontext des AUTOSAR Virtual Function Bus (VFB). Es definiert die statische Struktur zur Modellierung von zeitlichen Garantien und Constraints (wie Latenzen und Höchstaltermuster) entlang von Wirkungsketten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong>TimingChainConstraintOrGuarantee</strong>: Zentrale Entität mit dem Attribut <code>- constraint or guarantee:</code>. Besitzt eine ungerichtete oder navigierbare Assoziation mit Multiplizität <code>*</code> zu <code>TimingChain</code> und eine gerichtete Assoziation zu <code>TimingChainModel</code>.</li>\n<li><strong>TimingChain</strong>: Repräsentiert die Wirkungskette. Verfügt über eine reflexive Assoziation mit Rollenname und Multiplizität <code>+segments 1..* {ordered}</code>, um geordnete Segmente von Timing-Ketten abzubilden.</li>\n<li><strong>TimingChainModel</strong>: Abstrakte Basisklasse (kursiv dargestellt) für konkrete Timing-Modelle.</li>\n<li><strong>MinMaxOneToOneModel</strong>: Spezialisierung von <code>TimingChainModel</code> (Generalisierungsbeziehung) mit den öffentlichen Attributen <code>+ minimum: TimeInterval</code> und <code>+ maximum: TimeInterval</code>.</li>\n<li><strong>MaxAgeModel</strong>: Spezialisierung von <code>TimingChainModel</code> mit dem öffentlichen Attribut <code>+ maxAge: TimeInterval</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles UML-Klassendiagramm stellt das Diagramm kein dynamisches Ausführungsverhalten oder Interaktionssequenzen dar. Es legt das metamodellbasierte Schema fest, über das Werkzeuge zur Entwurfs- und Konfigurationszeit Wirkungsketten in geordnete Segmente zerlegen und diesen segmentspezifische oder kettenweite Zeitintervalle (Minimal-/Maximallaufzeiten sowie Maximalalter von Datenflüssen) als Randbedingung oder Garantie zuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für AUTOSAR-VFB-Timing-Beschreibungen. Entwickler und Tool-Hersteller müssen sicherstellen, dass Instanzen von <code>TimingChain</code> aus mindestens einem geordneten Segment bestehen (<code>1..* {ordered}</code>). Bei Instanziierung von <code>MinMaxOneToOneModel</code> müssen die Attribute <code>minimum</code> und <code>maximum</code> als <code>TimeInterval</code> typisiert und angegeben werden, bei <code>MaxAgeModel</code> das Attribut <code>maxAge</code>.</p>"}, {"id": "FIG-b5659463b1df61b4", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Modellen für Timing-Ketten (Timing Chains) und deren zeitlichen Randbedingungen im Kontext des AUTOSAR Virtual Function Bus (VFB). Es definiert die statische Struktur zur Modellierung von zeitlichen Garantien und Constraints (wie Latenzen und Höchstaltermuster) entlang von Wirkungsketten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong>TimingChainConstraintOrGuarantee</strong>: Zentrale Entität mit dem Attribut <code>- constraint or guarantee:</code>. Besitzt eine ungerichtete oder navigierbare Assoziation mit Multiplizität <code>*</code> zu <code>TimingChain</code> und eine gerichtete Assoziation zu <code>TimingChainModel</code>.</li>\n<li><strong>TimingChain</strong>: Repräsentiert die Wirkungskette. Verfügt über eine reflexive Assoziation mit Rollenname und Multiplizität <code>+segments 1..* {ordered}</code>, um geordnete Segmente von Timing-Ketten abzubilden.</li>\n<li><strong>TimingChainModel</strong>: Abstrakte Basisklasse (kursiv dargestellt) für konkrete Timing-Modelle.</li>\n<li><strong>MinMaxOneToOneModel</strong>: Spezialisierung von <code>TimingChainModel</code> (Generalisierungsbeziehung) mit den öffentlichen Attributen <code>+ minimum: TimeInterval</code> und <code>+ maximum: TimeInterval</code>.</li>\n<li><strong>MaxAgeModel</strong>: Spezialisierung von <code>TimingChainModel</code> mit dem öffentlichen Attribut <code>+ maxAge: TimeInterval</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles UML-Klassendiagramm stellt das Diagramm kein dynamisches Ausführungsverhalten oder Interaktionssequenzen dar. Es legt das metamodellbasierte Schema fest, über das Werkzeuge zur Entwurfs- und Konfigurationszeit Wirkungsketten in geordnete Segmente zerlegen und diesen segmentspezifische oder kettenweite Zeitintervalle (Minimal-/Maximallaufzeiten sowie Maximalalter von Datenflüssen) als Randbedingung oder Garantie zuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für AUTOSAR-VFB-Timing-Beschreibungen. Entwickler und Tool-Hersteller müssen sicherstellen, dass Instanzen von <code>TimingChain</code> aus mindestens einem geordneten Segment bestehen (<code>1..* {ordered}</code>). Bei Instanziierung von <code>MinMaxOneToOneModel</code> müssen die Attribute <code>minimum</code> und <code>maximum</code> als <code>TimeInterval</code> typisiert und angegeben werden, bei <code>MaxAgeModel</code> das Attribut <code>maxAge</code>.</p>"}], "trans": [{"from": "FIG-6b3b266bcaea8fc7", "to": "FIG-b5659463b1df61b4", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
